package be.winnetrie.mod.simpleserverutilities.network;
import be.winnetrie.mod.simpleserverutilities.SimpleServerUtilities;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.ResourceLocation;
public record MineDataPayload(boolean admin,String selectedId,String json,String notice,boolean error,long requestId) implements CustomPacketPayload{public static final Type<MineDataPayload> TYPE=new Type<>(ResourceLocation.fromNamespaceAndPath(SimpleServerUtilities.MODID,"mine_data"));public static final StreamCodec<RegistryFriendlyByteBuf,MineDataPayload> STREAM_CODEC=StreamCodec.of(MineDataPayload::encode,MineDataPayload::decode);public MineDataPayload{selectedId=PayloadBounds.string(selectedId,64);json=PayloadBounds.string(json,65535);notice=PayloadBounds.string(notice,1024);requestId=Math.max(0L,requestId);}private static void encode(RegistryFriendlyByteBuf b,MineDataPayload p){b.writeBoolean(p.admin);b.writeUtf(p.selectedId,64);b.writeUtf(p.json,65535);b.writeUtf(p.notice,1024);b.writeBoolean(p.error);b.writeVarLong(p.requestId);}private static MineDataPayload decode(RegistryFriendlyByteBuf b){return new MineDataPayload(b.readBoolean(),b.readUtf(64),b.readUtf(65535),b.readUtf(1024),b.readBoolean(),b.readVarLong());}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
